export interface GameState {
  roomsCleared: number;
  level: number;
  xp: number;
  xpToNext: number;
  gold: number;
  health: number;
  maxHealth: number;
  equipment: Equipment;
  partyMembers: PartyMember[];
}

export interface Equipment {
  weapon: Weapon | null;
  armor: Armor | null;
  accessory: Accessory | null;
}

export interface Item {
  id: string;
  name: string;
  cost: number;
}

export interface Weapon extends Item {
  damage: number;
  fireRate: number;
  speed: number;
}

export interface Armor extends Item {
  defense: number;
  health: number;
}

export interface Accessory extends Item {
  effect: string;
}

export interface PartyMember {
  id: string;
