import { GameState, Equipment, PartyMember, Weapon, Armor, Accessory } from '../types/index';

export class GameStateManager {
  private state: GameState;

  constructor() {
    this.state = {
      roomsCleared: 0,
      level: 1,
      xp: 0,
      xpToNext: 25,
      gold: 100,
      health: 100,
      maxHealth: 100,
      equipment: {
        weapon: {
          id: 'starter_sword',
          name: 'Iron Sword',
          cost: 0,
          damage: 15,
          fireRate: 0.2,
          speed: 400,
        },
        armor: null,
        accessory: null,
      },
      partyMembers: [],
    };
  }

  getState(): GameState {
    return this.state;
  }

  setState(state: Partial<GameState>): void {
    this.state = { ...this.state, ...state };
  }

  addXP(amount: number): boolean {
    this.state.xp += amount;
    if (this.state.xp >= this.state.xpToNext) {
      this.state.xp -= this.state.xpToNext;
      this.state.level += 1;
      this.state.xpToNext = Math.floor(this.state.xpToNext * 1.25) + 5;
      this.state.health = Math.min(this.state.maxHealth, this.state.health + 15);
      this.state.maxHealth += 5;
      return true;
    }
    return false;
  }

  addGold(amount: number): void {
    this.state.gold += amount;
  }

  addPartyMember(member: PartyMember): void {
    this.state.partyMembers.push(member);
  }

  equipWeapon(weapon: Weapon): void {
    if (this.state.equipment.weapon) {
      this.state.gold += Math.floor(this.state.equipment.weapon.cost * 0.5);
    }
    this.state.equipment.weapon = weapon;
  }

  equipArmor(armor: Armor): void {
    if (this.state.equipment.armor) {
      this.state.gold += Math.floor(this.state.equipment.armor.cost * 0.5);
    }
    this.state.equipment.armor = armor;
  }

  heal(amount: number): void {
    this.state.health = Math.min(this.state.maxHealth, this.state.health + amount);
  }

  takeDamage(amount: number): void {
    const reduction = this.state.equipment.armor ? this.state.equipment.armor.defense : 0;
    const actualDamage = Math.max(1, amount - reduction);
    this.state.health = Math.max(0, this.state.health - actualDamage);
  }

  reset(): void {
    this.state = {
      ...this.state,
      roomsCleared: 0,
      level: 1,
      xp: 0,
      xpToNext: 25,
      health: this.state.maxHealth,
    };
  }
}

