import Phaser from 'phaser';
import { GameStateManager } from '../utils/GameStateManager';

export class Player extends Phaser.Physics.Arcade.Sprite {
  private gameState: GameStateManager;
  private lastFireTime: number = 0;
  private dashCooldown: number = 0;
  private dashDuration: number = 0.2;
  private isDashing: boolean = false;

  constructor(scene: Phaser.Scene, x: number, y: number, gameState: GameStateManager) {
    super(scene, x, y, '');
    this.gameState = gameState;

    scene.add.existing(this);
    scene.physics.add.existing(this);

    this.setCollideWorldBounds(true);
    this.setBounce(0.2);
    this.setScale(1);
    this.setDrag(0);

    // Create simple circle graphics
    const graphics = scene.make.graphics({ x: 0, y: 0, add: false });
    graphics.fillStyle(0x4488ff, 1);
    graphics.fillCircle(12, 12, 12);
    graphics.generateTexture('player_sprite', 24, 24);
    graphics.destroy();

    this.setTexture('player_sprite');
  }

  update(cursors: Phaser.Types.Input.Keyboard.CursorKeys, pointer: Phaser.Input.Pointer): void {
    const speed = 250;
    const vx = (cursors.right.isDown ? 1 : 0) - (cursors.left.isDown ? 1 : 0);
    const vy = (cursors.down.isDown ? 1 : 0) - (cursors.up.isDown ? 1 : 0);

    const velocity = new Phaser.Math.Vector2(vx, vy).normalize().scale(speed);
    this.setVelocity(velocity.x, velocity.y);

    // Face pointer
    this.rotation = Phaser.Math.Angle.Between(this.x, this.y, pointer.x, pointer.y);

    // Dash cooldown
    if (this.dashCooldown > 0) {
      this.dashCooldown -= this.scene.game.loop.delta / 1000;
    }

    // Dash
    if (Phaser.Input.Keyboard.JustDown(cursors.space) && this.dashCooldown <= 0) {
      this.dash();
    }

    // Update dash state
    if (this.isDashing) {
      this.dashDuration -= this.scene.game.loop.delta / 1000;
      if (this.dashDuration <= 0) {
        this.isDashing = false;
        this.setAlpha(1);
      }
    }
  }

  private dash(): void {
    this.isDashing = true;
    this.dashCooldown = 1.5;
    this.dashDuration = 0.2;
    this.setAlpha(0.5);

    const dir = new Phaser.Math.Vector2(
      Math.cos(this.rotation),
      Math.sin(this.rotation)
    );
    this.setVelocity(dir.x * 600, dir.y * 600);
  }

  shoot(pointer: Phaser.Input.Pointer): Phaser.Physics.Arcade.Sprite | null {
    const now = this.scene.time.now;
    const state = this.gameState.getState();
    const weapon = state.equipment.weapon;

    if (!weapon || now - this.lastFireTime < weapon.fireRate * 1000) {
      return null;
    }

    this.lastFireTime = now;

    const dir = new Phaser.Math.Vector2(
      Math.cos(this.rotation),
      Math.sin(this.rotation)
    );

    const bullet = this.scene.physics.add.sprite(
      this.x + dir.x * 20,
      this.y + dir.y * 20,
      ''
    );

    // Draw bullet
    const graphics = this.scene.make.graphics({ x: 0, y: 0, add: false });
    graphics.fillStyle(0xffff00, 1);
    graphics.fillCircle(3, 3, 3);
    graphics.generateTexture('bullet_sprite', 6, 6);
    graphics.destroy();

    bullet.setTexture('bullet_sprite');
    bullet.setVelocity(dir.x * weapon.speed, dir.y * weapon.speed);
    bullet.setData('damage', weapon.damage);

    return bullet;
  }

  takeDamage(amount: number): void {
    if (this.isDashing) return;
    this.gameState.takeDamage(amount);
  }

  getIsDashing(): boolean {
    return this.isDashing;
  }
}

