import { Enemy } from '../entities/Enemy';
import { PartyMember } from '../entities/PartyMember';
import { GameStateManager } from '../utils/GameStateManager';
import { PARTY_MEMBERS } from '../utils/Shop';

export class GameScene extends Phaser.Scene {
  private player!: Player;
  private gameState: GameStateManager;
  private enemies: Enemy[] = [];
  private partyMembers: PartyMember[] = [];
  private cursors!: Phaser.Types.Input.Keyboard.CursorKeys;
  private spawnTimer: number = 0;
  private spawnInterval: number = 2;
  private currentWave: number = 0;
  private enemiesSpawnedThisWave: number = 0;
  private enemiesKilledThisWave: number = 0;
  private hud!: Phaser.GameObjects.Container;

  constructor() {
    super('GameScene');
    this.gameState = new GameStateManager();
  }

  create(): void {
    // Input
    this.cursors = this.input.keyboard!.createCursorKeys();
    this.input.keyboard!.addKeys('W,A,S,D,SPACE');

    // Player
    this.player = new Player(this, this.cameras.main.centerX, this.cameras.main.centerY, this.gameState);

    // Party members
    this.addPartyMember(PARTY_MEMBERS[0]); // Start with Thorin

    // Physics groups
    this.physics.add.overlap(this.player, this.enemies, this.handlePlayerEnemyCollision, undefined, this);

    // HUD
    this.createHUD();

    // Spawn first wave
    this.currentWave = 1;
  }

  private addPartyMember(memberData: any): void {
    const member = new PartyMember(this, memberData, this.player);
    this.partyMembers.push(member);
    this.gameState.addPartyMember(memberData);
  }

  private createHUD(): void {
    const state = this.gameState.getState();

    const hpText = this.add.text(20, 20, `HP: ${state.health}/${state.maxHealth}`, {
      fontSize: '16px',
      color: '#ffff00',
    });

    const levelText = this.add.text(20, 50, `Level: ${state.level}`, {
      fontSize: '16px',
      color: '#ffff00',
    });

    const goldText = this.add.text(this.cameras.main.width - 200, 20, `Gold: ${state.gold}`, {
      fontSize: '16px',
      color: '#ffff00',
    });

    const roomText = this.add.text(this.cameras.main.width - 200, 50, `Room: ${state.roomsCleared}`, {
      fontSize: '16px',
      color: '#ffff00',
    });

    const waveText = this.add.text(this.cameras.main.centerX - 50, 20, `Wave: ${this.currentWave}`, {
      fontSize: '16px',
      color: '#ffff00',
    });

    // Update HUD every frame
    this.events.on('update', () => {
      const state = this.gameState.getState();
      hpText.setText(`HP: ${state.health}/${state.maxHealth}`);
      levelText.setText(`Level: ${state.level}`);
      goldText.setText(`Gold: ${state.gold}`);
      roomText.setText(`Room: ${state.roomsCleared}`);
      waveText.setText(`Wave: ${this.currentWave}`);

      if (state.health <= 0) {
        this.scene.start('UpgradeScene', { gameState: this.gameState, victory: false });
      }
    });
  }

  update(): void {
    // Player update
    this.player.update(this.cursors, this.input.activePointer);

    // Player shooting
    if (this.input.activePointer.isDown) {
      const bullet = this.player.shoot(this.input.activePointer);
      if (bullet) {
        // Check collision with enemies
        this.physics.overlap(bullet, this.enemies, (playerBullet: any, enemy: any) => {
          const dmg = playerBullet.getData('damage') || 10;
          enemy.takeDamage(dmg);
          playerBullet.destroy();

          if (enemy.isDead()) {
            this.gameState.addXP(enemy.xpReward);
            this.gameState.addGold(enemy.xpReward / 2);
            this.enemies = this.enemies.filter(e => e !== enemy);
            enemy.destroy();
            this.enemiesKilledThisWave++;
          }
        });
      }
    }

    // Party members update
    this.partyMembers.forEach(member => member.update());

    // Enemy updates
    this.enemies.forEach(enemy => {
      enemy.update();

      // Check for dead enemies
      if (enemy.isDead()) {
        this.enemies = this.enemies.filter(e => e !== enemy);
        enemy.destroy();
        this.enemiesKilledThisWave++;
      }
    });

    // Enemy bullets hit player
    const enemyBullets = this.children.list.filter(
      (child: any) => child.getData && child.getData('isEnemyBullet')
    );
    enemyBullets.forEach((bullet: any) => {
      if (Phaser.Physics.Arcade.Distance.Between(this.player, bullet) < 20) {
        if (!this.player.getIsDashing()) {
          this.player.takeDamage(bullet.getData('damage') || 5);
        }
        bullet.destroy();
      }
    });

    // Spawn enemies
    this.spawnTimer += this.game.loop.delta / 1000;
    if (this.spawnTimer > this.spawnInterval && this.enemiesSpawnedThisWave < this.currentWave * 3 + 2) {
      this.spawnTimer = 0;
      this.spawnEnemy();
    }

    // Wave complete
    if (this.enemiesKilledThisWave >= this.currentWave * 3 + 2 && this.enemies.length === 0) {
      this.currentWave++;
      this.enemiesSpawnedThisWave = 0;
      this.enemiesKilledThisWave = 0;

      if (this.currentWave > 5) {
        this.gameState.setState({ roomsCleared: (this.gameState.getState().roomsCleared || 0) + 1 });
        this.scene.start('UpgradeScene', { gameState: this.gameState, victory: true });
      }
    }
  }

  private spawnEnemy(): void {
    const angle = Math.random() * Math.PI * 2;
    const x = this.player.x + Math.cos(angle) * 300;
    const y = this.player.y + Math.sin(angle) * 300;

    const types: Array<'goblin' | 'orc' | 'mage' | 'boss'> = ['goblin', 'orc', 'mage'];
    if (this.currentWave > 3) types.push('boss');

    const type = Phaser.Utils.Array.GetRandom(types);
    const enemy = new Enemy(this, x, y, type, this.player);
    this.enemies.push(enemy);
    this.enemiesSpawnedThisWave++;
  }

  private handlePlayerEnemyCollision(): void {
    if (!this.player.getIsDashing()) {
      this.player.takeDamage(5);
    }
  }
}

