import Phaser from 'phaser';
import { GameStateManager } from '../utils/GameStateManager';
import { WEAPONS, ARMOR, PARTY_MEMBERS } from '../utils/Shop';

export class UpgradeScene extends Phaser.Scene {
  private gameState!: GameStateManager;
  private selectedTab: 'heal' | 'weapons' | 'armor' | 'party' = 'heal';
  private victory: boolean = false;

  constructor() {
    super('UpgradeScene');
  }

  init(data: any): void {
    this.gameState = data.gameState;
    this.victory = data.victory;
  }

  create(): void {
    const state = this.gameState.getState();

    // Background
    this.cameras.main.setBackgroundColor('#222222');

    // Title
    const title = this.victory ? 'Room Cleared!' : 'Game Over';
    this.add.text(this.cameras.main.centerX, 50, title, {
      fontSize: '32px',
      color: this.victory ? '#00ff00' : '#ff0000',
    }).setOrigin(0.5);

    // Stats
    const statsText = `Level: ${state.level} | Gold: ${state.gold} | Rooms: ${state.roomsCleared}`;
    this.add.text(this.cameras.main.centerX, 100, statsText, {
      fontSize: '16px',
      color: '#ffff00',
    }).setOrigin(0.5);

    if (!this.victory) {
      const restartText = this.add.text(this.cameras.main.centerX, this.cameras.main.height - 50, 'Click to Restart', {
        fontSize: '20px',
        color: '#ffffff',
      }).setOrigin(0.5);

      this.input.once('pointerdown', () => {
        this.gameState.reset();
        this.scene.start('GameScene');
      });

      return;
    }

    // Tabs
    const tabY = 150;
    const tabs = ['heal', 'weapons', 'armor', 'party'];
    tabs.forEach((tab, i) => {
      const tabText = this.add
        .text(100 + i * 250, tabY, tab.toUpperCase(), {
          fontSize: '16px',
          color: '#ffffff',
          backgroundColor: this.selectedTab === tab ? '#0080ff' : '#444444',
          padding: { x: 10, y: 5 },
        })
        .setInteractive({ useHandCursor: true })
        .on('pointerdown', () => {
          this.selectedTab = tab as any;
          this.scene.restart();
        });
    });

    // Content based on tab
    const contentY = 220;
    const listX = 50;
    const listY = contentY;

    if (this.selectedTab === 'heal') {
      this.createHealTab(listX, listY, state);
    } else if (this.selectedTab === 'weapons') {
      this.createWeaponsTab(listX, listY, state);
    } else if (this.selectedTab === 'armor') {
      this.createArmorTab(listX, listY, state);
    } else if (this.selectedTab === 'party') {
      this.createPartyTab(listX, listY, state);
    }

    // Continue button
    const continueText = this.add
      .text(this.cameras.main.centerX, this.cameras.main.height - 50, 'Continue to Next Room (Space)', {
        fontSize: '16px',
        color: '#00ff00',
      })
      .setOrigin(0.5)
      .setInteractive({ useHandCursor: true })
      .on('pointerdown', () => {
        this.scene.start('GameScene', { gameState: this.gameState });
      });

    this.input.keyboard!.on('keydown-SPACE', () => {
      this.scene.start('GameScene', { gameState: this.gameState });
    });
  }

  private createHealTab(x: number, y: number, state: any): void {
    const healing = 30;
    const cost = 20;

    const text = `Heal ${healing} HP for ${cost} gold`;
    this.add.text(x, y, text, { fontSize: '16px', color: '#ffffff' });

    const healBtn = this.add
      .text(x, y + 40, 'Heal', {
        fontSize: '14px',
        color: state.gold >= cost ? '#00ff00' : '#ff0000',
        backgroundColor: '#444444',
        padding: { x: 10, y: 5 },
      })
      .setInteractive({ useHandCursor: true })
      .on('pointerdown', () => {
        if (state.gold >= cost) {
          state.gold -= cost;
          this.gameState.heal(healing);
          this.scene.restart();
        }
      });
  }

  private createWeaponsTab(x: number, y: number, state: any): void {
    const currentWeapon = state.equipment.weapon?.id;

    WEAPONS.forEach((weapon, i) => {
      const isEquipped = weapon.id === currentWeapon;
      const canAfford = state.gold >= weapon.cost;

      const color = isEquipped ? '#ffff00' : canAfford ? '#00ff00' : '#ff0000';
      const text = `${weapon.name} (Dmg: ${weapon.damage}) - ${weapon.cost}g ${isEquipped ? '[EQUIPPED]' : ''}`;

      const weaponBtn = this.add
        .text(x, y + i * 40, text, { fontSize: '14px', color, backgroundColor: '#444444', padding: { x: 10, y: 5 } })
        .setInteractive({ useHandCursor: true })
        .on('pointerdown', () => {
          if (!isEquipped && canAfford) {
            state.gold -= weapon.cost;
            this.gameState.equipWeapon(weapon);
            this.scene.restart();
          }
        });
    });
  }

  private createArmorTab(x: number, y: number, state: any): void {
    const currentArmor = state.equipment.armor?.id;

    ARMOR.forEach((armor, i) => {
      const isEquipped = armor.id === currentArmor;
      const canAfford = state.gold >= armor.cost;

      const color = isEquipped ? '#ffff00' : canAfford ? '#00ff00' : '#ff0000';
      const text = `${armor.name} (Def: ${armor.defense}) - ${armor.cost}g ${isEquipped ? '[EQUIPPED]' : ''}`;

      const armorBtn = this.add
        .text(x, y + i * 40, text, { fontSize: '14px', color, backgroundColor: '#444444', padding: { x: 10, y: 5 } })
        .setInteractive({ useHandCursor: true })
        .on('pointerdown', () => {
          if (!isEquipped && canAfford) {
            state.gold -= armor.cost;
            this.gameState.equipArmor(armor);
            this.scene.restart();
          }
        });
    });
  }

  private createPartyTab(x: number, y: number, state: any): void {
    const recruited = state.partyMembers.map((m: any) => m.id);

    PARTY_MEMBERS.forEach((member, i) => {
      const isRecruited = recruited.includes(member.id);
      const color = isRecruited ? '#ffff00' : '#00ff00';
      const text = `${member.name} (${member.class}) ${isRecruited ? '[RECRUITED]' : '- 50g'}`;

      const memberBtn = this.add
        .text(x, y + i * 40, text, { fontSize: '14px', color, backgroundColor: '#444444', padding: { x: 10, y: 5 } })
        .setInteractive({ useHandCursor: true })
        .on('pointerdown', () => {
          if (!isRecruited && state.gold >= 50) {
            state.gold -= 50;
            this.gameState.addPartyMember(member);
            this.scene.restart();
          }
        });
    });
  }
}

