      this.fireShot((Math.PI * 2 * i) / 6);
    }
  } else if (this.type === 'boss') {
    for (let i = 0; i < 8; i++) {
      this.fireShot((Math.PI * 2 * i) / 8);
    }
    this.shootInterval = 0.8;
  }
}

