private firePattern(): void {
  if (!this.target) return;

  if (this.type === 'goblin') {
    this.fireShot(0);
  } else if (this.type === 'orc') {
    const angles = [-Math.PI / 6, 0, Math.PI / 6];
    angles.forEach(offset => {
      const angle = Phaser.Math.Angle.Between(this.x, this.y, this.target!.x, this.target!.y) + offset;
      this.fireShot(angle);
    });
  } else if (this.type === 'mage') {
    for (let i = 0; i < 6; i++) {
      this.fireShot((Math.PI * 2 * i) / 6);
    }
  } else if (this.type === 'skeleton') {
    // Skeleton: Aimed burst (3 bullets in spread)
    const centerAngle = Phaser.Math.Angle.Between(this.x, this.y, this.target.x, this.target.y);
    for (let i = -1; i <= 1; i++) {
      this.fireShot(centerAngle + (i * Math.PI / 12));
    }
    this.shootInterval = 1.2;
  } else if (this.type === 'spider') {
    // Spider: Fast spiraling shots
    const angle = Phaser.Math.Angle.Between(this.x, this.y, this.target.x, this.target.y);
    for (let i = 0; i < 4; i++) {
      this.fireShot(angle + (Math.PI / 2) * i);
    }
    this.shootInterval = 0.5;
  } else if (this.type === 'cultist') {
    // Cultist: Chaotic bursts
    for (let i = 0; i < 5; i++) {
      const randomAngle = Math.random() * Math.PI * 2;
      this.fireShot(randomAngle);
    }
    this.shootInterval = 1.5;
  } else if (this.type === 'wraith') {
    // Wraith: Wavering spiral
    for (let i = 0; i < 8; i++) {
      this.fireShot((Math.PI * 2 * i) / 8);
    }
    this.shootInterval = 1;
  } else if (this.type === 'dragon') {
    // Dragon: Massive spread
    for (let i = 0; i < 12; i++) {
      this.fireShot((Math.PI * 2 * i) / 12);
    }
    this.shootInterval = 1.2;
  } else if (this.type === 'lich') {
    // Lich: Complex pattern with aimed + circle
    const centerAngle = Phaser.Math.Angle.Between(this.x, this.y, this.target.x, this.target.y);
    for (let i = 0; i < 10; i++) {
      this.fireShot((Math.PI * 2 * i) / 10);
    }
    for (let i = -2; i <= 2; i++) {
      this.fireShot(centerAngle + (i * Math.PI / 20));
    }
    this.shootInterval = 0.9;
  }
}

