import Phaser from 'phaser';
import { GameStateManager } from '../utils/GameStateManager';
import { getRandomUpgrades } from '../utils/UpgradePool';

export class UpgradeSelectScene extends Phaser.Scene {
  private gameState!: GameStateManager;
  private selectedUpgrade: any = null;

  constructor() {
    super('UpgradeSelectScene');
  }

  init(data: any): void {
    this.gameState = data.gameState;
  }

  create(): void {
    // Background
    this.cameras.main.setBackgroundColor('#1a1a2e');

    // Title
    this.add.text(this.cameras.main.centerX, 40, 'Choose an Upgrade', {
      fontSize: '32px',
      color: '#00ff00',
      fontStyle: 'bold',
    }).setOrigin(0.5);

    // Get 3 random upgrades
    const upgrades = getRandomUpgrades(3);

    // Display upgrade options
    const cardWidth = 280;
    const cardHeight = 200;
    const spacing = 30;
    const startX = (this.cameras.main.width - (cardWidth * 3 + spacing * 2)) / 2;
    const startY = 150;

    upgrades.forEach((upgrade, i) => {
      const cardX = startX + i * (cardWidth + spacing);
      const cardY = startY;

      const card = this.add.rectangle(cardX, cardY, cardWidth, cardHeight, 0x2d2d4d);
      card.setStrokeStyle(2, 0x00ff00);
      card.setInteractive({ useHandCursor: true })
        .on('pointerdown', () => {
          this.selectUpgrade(upgrade);
        })
        .on('pointerover', () => {
          card.setStrokeStyle(3, 0xffff00);
        })
        .on('pointerout', () => {
          card.setStrokeStyle(2, this.selectedUpgrade?.id === upgrade.id ? 0x00ff00 : 0x0088ff);
        });

      // Icon
      this.add.text(cardX, cardY - 60, upgrade.icon, {
        fontSize: '64px',
      }).setOrigin(0.5);

      // Name
      this.add.text(cardX, cardY - 15, upgrade.name, {
        fontSize: '18px',
        color: '#ffffff',
        fontStyle: 'bold',
      }).setOrigin(0.5);

      // Description
      const descText = this.add.text(cardX, cardY + 25, upgrade.description, {
        fontSize: '14px',
        color: '#aaaaaa',
        align: 'center',
        wordWrap: { width: cardWidth - 20 },
      }).setOrigin(0.5);

      // Type
      const typeColor = upgrade.type === 'stat' ? '#4488ff' : upgrade.type === 'ability' ? '#ff8844' : '#88ff44';
      this.add.text(cardX, cardY + 75, upgrade.type.toUpperCase(), {
        fontSize: '12px',
        color: typeColor,
      }).setOrigin(0.5);
    });

    // Continue button
    const continueBtn = this.add
      .text(this.cameras.main.centerX, this.cameras.main.height - 60, 'Continue (Space or Click)', {
        fontSize: '16px',
        color: '#00ff00',
        backgroundColor: '#004400',
        padding: { x: 15, y: 10 },
      })
      .setOrigin(0.5)
      .setInteractive({ useHandCursor: true })
      .on('pointerdown', () => {
        this.continueGame();
      });

    this.input.keyboard!.on('keydown-SPACE', () => {
      this.continueGame();
    });
  }

  private selectUpgrade(upgrade: any): void {
    this.selectedUpgrade = upgrade;
    this.gameState.applyUpgrade(upgrade);
  }

  private continueGame(): void {
    if (this.selectedUpgrade) {
      this.scene.start('GameScene', { gameState: this.gameState });
    }
  }
}

