        })
        .on('pointerover', () => {
          card.setStrokeStyle(3, 0xffff00);
        })
        .on('pointerout', () => {
          card.setStrokeStyle(2, this.selectedUpgrade?.id === upgrade.id ? 0x00ff00 : 0x0088ff);
        });

      // Icon
      this.add.text(cardX, cardY - 60, upgrade.icon, {
        fontSize: '64px',
      }).setOrigin(0.5);

      // Name
      this.add.text(cardX, cardY - 15, upgrade.name, {
        fontSize: '18px',
        color: '#ffffff',
        fontStyle: 'bold',
      }).setOrigin(0.5);

      // Description
      const descText = this.add.text(cardX, cardY + 25, upgrade.description, {
        fontSize: '14px',
        color: '#aaaaaa',
        align: 'center',
        wordWrap: { width: cardWidth - 20 },
      }).setOrigin(0.5);

      // Type
      const typeColor = upgrade.type === 'stat' ? '#4488ff' : upgrade.type === 'ability' ? '#ff8844' : '#88ff44';
      this.add.text(cardX, cardY + 75, upgrade.type.toUpperCase(), {
        fontSize: '12px',
        color: typeColor,
      }).setOrigin(0.5);
    });

    // Continue button
    const continueBtn = this.add
      .text(this.cameras.main.centerX, this.cameras.main.height - 60, 'Continue (Space or Click)', {
        fontSize: '16px',
        color: '#00ff00',
        backgroundColor: '#004400',
        padding: { x: 15, y: 10 },
      })
      .setOrigin(0.5)
      .setInteractive({ useHandCursor: true })
      .on('pointerdown', () => {
        this.continueGame();
      });

    this.input.keyboard!.on('keydown-SPACE', () => {
      this.continueGame();
    });
  }

  private selectUpgrade(upgrade: any): void {
    this.selectedUpgrade = upgrade;
    this.gameState.applyUpgrade(upgrade);
  }

  private continueGame(): void {
    if (this.selectedUpgrade) {
      this.scene.start('GameScene', { gameState: this.gameState });
    }
  }
}

