      wolf: 0x8844ff,
      dragon: 0xff3300,
      golem: 0x888888,
      fairy: 0xffff99,
      familiar: 0x00ffcc,
      phoenix: 0xffaa00,
    };

    const graphics = this.scene.make.graphics({ x: 0, y: 0, add: false });
    graphics.fillStyle(colors[this.data.type], 1);
    graphics.fillCircle(12, 12, 12);
    graphics.lineStyle(2, 0xffffff, 1);
    graphics.strokeCircle(12, 12, 12);

    // Add symbol
    graphics.fillStyle(0xffffff, 0.8);
    const symbols: Record<PetType, string> = {
      wolf: '🐺',
      dragon: '🐉',
      golem: '⛏️',
      fairy: '✨',
      familiar: '🦉',
      phoenix: '🔥',
    };

    graphics.generateTexture(`pet_${this.data.type}`, 24, 24);
    graphics.destroy();

    this.setTexture(`pet_${this.data.type}`);
  }

  update(): void {
    if (!this.target || !this.target.active) {
      return;
    }

    // Follow player at offset
    const targetX = this.target.x + this.offset.x;
    const targetY = this.target.y + this.offset.y;

    const dir = new Phaser.Math.Vector2(targetX - this.x, targetY - this.y);
    if (dir.length() > 1) {
      dir.normalize();
      this.setVelocity(dir.x * this.data.speed, dir.y * this.data.speed);
    } else {
      this.setVelocity(0, 0);
    }

    // Rotate to face target
    if (this.target) {
      this.rotation = Phaser.Math.Angle.Between(this.x, this.y, this.target.x, this.target.y);
    }

    // Attack
    this.shootTimer += this.scene.game.loop.delta / 1000;
    if (this.shootTimer > this.data.attackSpeed) {
      this.shootTimer = 0;
      this.attack();
    }
  }

  private attack(): void {
    // Find nearest enemy within range
    const enemies = this.scene.physics.world.colliders.entries
      .filter(c => c.object1?.getData?.('isEnemy') || c.object2?.getData?.('isEnemy'))
      .map(c => (c.object1?.getData?.('isEnemy') ? c.object1 : c.object2));

    if (enemies.length === 0) return;

    let nearest = enemies[0];
    let minDist = Phaser.Math.Distance.Between(this.x, this.y, nearest.x, nearest.y);

    for (const enemy of enemies) {
      const dist = Phaser.Math.Distance.Between(this.x, this.y, enemy.x, enemy.y);
      if (dist < minDist && dist < 300) {
        nearest = enemy;
        minDist = dist;
      }
    }

    if (minDist > 300) return;

    const angle = Phaser.Math.Angle.Between(this.x, this.y, nearest.x, nearest.y);

    // Different attack patterns per pet
    switch (this.data.type) {
      case 'wolf':
        this.fireShot(angle);
        break;
      case 'dragon':
        for (let i = -1; i <= 1; i++) {
          this.fireShot(angle + (i * Math.PI / 12));
        }
        break;
      case 'golem':
        this.fireShot(angle);
        break;
      case 'fairy':
        for (let i = 0; i < 3; i++) {
          this.fireShot(angle + (Math.PI / 6) * i);
        }
        break;
      case 'familiar':
        this.fireShot(angle);
        this.fireShot(angle + Math.PI / 8);
        break;
      case 'phoenix':
        for (let i = 0; i < 4; i++) {
          this.fireShot(angle + (Math.PI / 4) * i);
        }
        break;
    }
  }

  private fireShot(angle: number): void {
    const bullet = this.scene.physics.add.sprite(this.x, this.y, '');

    const graphics = this.scene.make.graphics({ x: 0, y: 0, add: false });
    graphics.fillStyle(0x00ff99, 1);
    graphics.fillCircle(2, 2, 2);
    graphics.generateTexture('pet_bullet', 4, 4);
    graphics.destroy();

    bullet.setTexture('pet_bullet');
    bullet.setVelocity(Math.cos(angle) * 250, Math.sin(angle) * 250);
    bullet.setData('damage', this.data.damage);
    bullet.setData('isPetBullet', true);

    this.scene.time.delayedCall(3000, () => {
      bullet.destroy();
    });
  }

  levelUp(): void {
    this.data.level += 1;
    this.data.health = this.data.maxHealth;
    this.data.maxHealth += 10;
    this.data.damage += 5;
  }

  takeDamage(amount: number): void {
    this.data.health -= amount;
    this.setAlpha(0.6);
    this.scene.time.delayedCall(100, () => {
      if (this.active) this.setAlpha(1);
    });
  }

  isDead(): boolean {
    return this.data.health <= 0;
  }
}

